function creerSubject() {
  let observers = [];
  let closed = false;
  let hasError = false;
  let errorValue = null;
  let isComplete = false;

  return {
    next(val) {
      if (closed || hasError || isComplete) return;
      observers.slice().forEach(o => {
        if (o.next) o.next(val);
      });
    },
    error(err) {
      if (closed || hasError || isComplete) return;
      hasError = true;
      errorValue = err;
      closed = true;
      observers.slice().forEach(o => {
        if (o.error) o.error(err);
      });
      observers = [];
    },
    complete() {
      if (closed || hasError || isComplete) return;
      isComplete = true;
      closed = true;
      observers.slice().forEach(o => {
        if (o.complete) o.complete();
      });
      observers = [];
    },
    subscribe(observer) {
      const o = observer || {};
      if (hasError) {
        if (o.error) o.error(errorValue);
        return { unsubscribe() {} };
      }
      if (isComplete) {
        if (o.complete) o.complete();
        return { unsubscribe() {} };
      }
      if (closed) return { unsubscribe() {} };
      observers.push(o);
      let unsubscribed = false;
      return {
        unsubscribe() {
          if (unsubscribed) return;
          unsubscribed = true;
          observers = observers.filter(x => x !== o);
        }
      };
    }
  };
}
