function memoiserAsync(fn) {
  const cache = new Map();
  return async function(...args) {
    const key = JSON.stringify(args);
    if (cache.has(key)) {
      return cache.get(key);
    }
    const promise = (async () => {
      try {
        const result = await fn(...args);
        // keep resolved value cached as resolved promise
        // replace with Promise.resolve(result) to avoid holding original promise chain
        cache.set(key, Promise.resolve(result));
        return result;
      } catch (e) {
        cache.delete(key);
        throw e;
      }
    })();
    cache.set(key, promise);
    return promise;
  };
}
