function creerCircuitBreaker(fn, seuil, delaiResetMs) {
  let failures = 0;
  let state = 'CLOSED'; // CLOSED, OPEN, HALF_OPEN
  let nextAttempt = 0;

  async function wrapped(...args) {
    if (state === 'OPEN') {
      if (Date.now() < nextAttempt) {
        throw new Error('Circuit open');
      }
      state = 'HALF_OPEN';
    }
    try {
      const result = await fn(...args);
      // success
      if (state === 'HALF_OPEN') {
        state = 'CLOSED';
      }
      failures = 0;
      return result;
    } catch (e) {
      failures++;
      if (state === 'HALF_OPEN' || failures >= seuil) {
        state = 'OPEN';
        nextAttempt = Date.now() + delaiResetMs;
      }
      throw e;
    }
  }
  wrapped.getState = () => state;
  wrapped.reset = () => { state = 'CLOSED'; failures = 0; nextAttempt = 0; };
  return wrapped;
}
