function remplirMatrice(grille, x, y, nouvelleValeur) {
    if (!grille || grille.length === 0) return grille;
    const rows = grille.length;
    const cols = grille[0].length;
    if (y < 0 || y >= rows || x < 0 || x >= cols) return grille;
    const ancienneValeur = grille[y][x];
    if (ancienneValeur === nouvelleValeur) return grille;

    const stack = [[x, y]];
    while (stack.length > 0) {
        const [cx, cy] = stack.pop();
        if (cy < 0 || cy >= rows || cx < 0 || cx >= cols) continue;
        if (grille[cy][cx] !== ancienneValeur) continue;
        grille[cy][cx] = nouvelleValeur;
        stack.push([cx + 1, cy], [cx - 1, cy], [cx, cy + 1], [cx, cy - 1]);
    }
    return grille;
}
